from common import *
def main():
    verify();q=json.loads((R/'QUALIFICATION.json').read_text());before=json.loads((R/'PRESERVATION_BEFORE.json').read_text());drift=[p for p,h in before.items() if not Path(p).is_file() or sha(Path(p))!=h];assert not drift
    failed=q['status']=='FAIL';assert not failed or (not (R/'targets').exists() and not (R/'TARGET_MANIFEST.json').exists())
    dev=json.loads((R/'DEVELOPMENT_RESULTS.json').read_text());qualification=json.loads((R/'QUALIFICATION_RESULTS.json').read_text()) if (R/'QUALIFICATION_RESULTS.json').exists() else []
    summaries=[]
    for condition in ['SAME_ONE','SAME_TWO','DIFF_ONE','DIFF_TWO']:
        rs=[x for x in qualification if not x['fixture'] and x['condition']==condition];good=[x for x in rs if x['status']=='COMPLETE'];row=dict(condition=condition,datasets=len(rs),complete=len(good),correct=sum(x.get('correct',False) for x in good),false_same_two=sum(x.get('predicted')=='SAME_TWO_KEYS' for x in good) if condition!='SAME_TWO' else None,D_positive=sum(x.get('D_null_p') is not None and x['D_null_p']<=.05 for x in good))
        for key in ['Q','D','Q0']:row[key+'_mean']=statistics.mean(x[key] for x in good) if good else None;row[key+'_sd']=statistics.stdev(x[key] for x in good) if len(good)>1 else None
        summaries.append(row)
    table(R/'QUALIFICATION_SUMMARY.csv',summaries);cells=q.get('separation_cells',[]);pc=q.get('physical_cells',[]);table(R/'SEPARATION_CELLS.csv',cells) if cells else None;table(R/'PHYSICAL_CELLS.csv',pc) if pc else None
    rows=['# Phase8: A/B structural alignment qualification','',f"Qualification: **{q['status']}**. {sum(x['cell_pass'] for x in cells)}/{len(cells)} separation cells and {sum(x['cell_pass'] for x in pc)}/{len(pc)} within-quire physical cells passed their registered gates.",'', 'The original Phase7 count/rejection failures remain unchanged. This is a separately requested experiment. Fixed keys alpha/beta1 are genuinely different published substitution tables and are never fitted; both key orientations are included. Native glyphs are shared, collision outputs retained and the same source segmentation used across keys.','']
    if failed:rows+=['**STOP. No Voynich A/B text graphs, learned mappings, alignment statistics or physical-similarity results were computed.** The method did not pass the registered separation/physical-control gate. No rescue, retuning, replacement keys, modified score, new bank or parameter sweep followed the failure.','']
    else:rows+=['Control qualification passed. Target results, if run, are in TARGET_RESULTS.json and targets/; the target manifest must precede target graph access.','']
    rows+=['## Held-out control separation','', '| Control | Complete / total | Correct category | False SAME_TWO_KEYS | D-null positives | Mean Q | Mean D |','|---|---:|---:|---:|---:|---:|---:|']
    for s in summaries:
        fmt=lambda x:'not available' if x is None else f'{x:.6f}'
        rows.append(f"| {s['condition']} | {s['complete']}/{s['datasets']} | {s['correct']} | {s['false_same_two']} | {s['D_positive']} | {fmt(s['Q_mean'])} | {fmt(s['D_mean'])} |")
    rows+=['','Q is held-out core-graph/frequency alignment, coverage-weighted. D subtracts native word-identity alignment. The fixed48-word core and bijective matching are approximations; author table collisions can violate bijectivity. FAQ is a fixed-budget approximate optimizer. Frequencies/graphs/vocabularies and mapping are trained only on each held-out-sheet complement; ground-truth unit mappings are not input.','', 'DEVELOPMENT and QUALIFICATION use disjoint normalized source characters and seeds. Equal-prior nearest centroids over development-standardized(Q,D) are frozen before qualification. Classifier categories are ONE_KEY (same source/single key), SAME_TWO_KEYS (same source/two keys), DIFFERENT (different sources under either key condition). They do not identify the language/meaning/historical generator of arbitrary text. Source/seed/noise variants are paired, not independent texts.','', 'The graph null reassigns A/B among whole leaves within fixed sheet-fold/observed-side-count strata, preserving sizes. A mere page-order shuffle would leave aggregate graphs invariant. All99 null assignments retrain vocabularies and mappings and score their held-out halves. Q and D nulls, supports, coverage, duplicate assignments and optimizer receipts are retained. These nulls assess the partition, not exclusively cipher causation.','', '## Within-quire mapped-graph conjugacy','', '| Base | Orientation | View | Control | Positive /5 | Cell pass |','|---|---:|---|---|---:|---|']
    for p in pc:rows.append(f"| {p['base']} | {p['orientation']} | {p['view']} | {p['condition']} | {p['positive']}/5 | {p['cell_pass']} |")
    rows+=['', 'Mappings/vocabularies for each tested quire are learned using all other quires; all tested leaves share that outside-trained coordinate system. Leaf profiles pool their sides/panels. Only conjugate-pair mapped graph/frequency similarity is compared with1999 within-quire whole-leaf permutations. Quire coherence and book-wide conjugacy were retired and are not computed. Physical positives intentionally clone source-unit content only within a conjugate pair; their detectability is not a claim about natural plaintext or real bifolio content. Independent-content same-source controls test unwanted conjugacy detections from key/layout artifacts.','', '## Full cell receipts','', 'See SEPARATION_CELLS.csv, PHYSICAL_CELLS.csv, QUALIFICATION_RESULTS.json, CLASSIFIER_FROZEN.json and each results/<dataset>/ folder. Failures retain the active stage and partial saved outputs, so score/optimizer/data-support failures are separate from unsuccessful control discrimination. Every control/key/source/noise specification and dataset/truth hash is frozen; no omitted failures.','', 'Naibbe glyph tables were designed using Voynich statistics and are NOT blind controls. This finite Latin/Italian/table/core-vocabulary calibration is not universal. Source substrings, imposed line-word layout, conditioning on A/B, limited word nodes, approximate mapping/bijection and paired noise/source draws constrain interpretation. Earlier ZL/H held-out analyses were already seen; a later qualified target analysis would be a registered retrospective extension.','',f"Preservation: {len(before)} pre-existing source/result/hold files are byte-identical. No earlier qualification file or gate was changed. No C12 sweep, C16 score, retired physical test or translation claim. Stop."]
    text='\n'.join(rows)+'\n'
    for a,b in [('fixed48','fixed 48'),('All99','All 99'),('with1999','with 1999')]:text=text.replace(a,b)
    (R/'REPORT.md').write_text(text,encoding='utf8');dump(R/'VERIFICATION.json',dict(status='PASS',qualification=q['status'],preserved_files=len(before),drift=drift,target_graphs_absent_on_failure=failed,retired_physical_tests_called=False,development_datasets=len(dev),qualification_datasets=len(qualification),original_failures_unchanged=True))
    dump(R/'OUTPUT_HASHES.json',{p.name:sha(p) for p in R.iterdir() if p.is_file() and p.name!='OUTPUT_HASHES.json'});print(json.dumps(dict(status='COMPLETE',qualification=q['status'],separation_pass=sum(x['cell_pass'] for x in cells),physical_pass=sum(x['cell_pass'] for x in pc),summary=summaries),indent=2))
if __name__=='__main__':main()
